// Verify x-signature = HMAC-SHA256(secret, rawBody).
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
const body = $json.body ? JSON.stringify($json.body) : '';
const sig = ($request.headers['x-signature'] || '');
const expected = crypto.createHmac('sha256', secret).update(body).digest('hex');
const ok = sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
if (!ok) throw new Error('invalid signature');
const p = $json.body;
return [{ json: { type: p.type, loanId: p.loanId, borrowerId: p.borrowerId, lenderId: p.lenderId, status: p.status, recipient: p.type === 'request_created' ? p.lenderId : p.borrowerId } }];

// Build the notification. In prod this maps recipient -> email via a
// directory lookup; the take-home mails a mock inbox (Mailpit, see compose).
const { recipient, type, loanId, status } = $json;
const subjects = { request_created: 'New borrow request', approved: 'Request approved', declined: 'Request declined', returned: 'Tool returned' };
return [{ json: { to: `${recipient}@demo.local`, subject: `${subjects[type] || 'Loan update'} — ${loanId}`, text: `Loan ${loanId}: ${type} (status ${status})` } }];
